#include <string>
#include <vector>

class Marcador {
public:
    int puntos() {
        return puntos_;
    }

    bool sumar_uno() {
        if (puntos_ >= 20) {
            return false;
        }

        ++puntos_;
        return true;
    }

private:
    int puntos_ = 0;
};

int main() {
    Marcador marcador;

    marcador.sumar_uno();

    std::cout << marcador.puntos();

    return 0;
}

