class RegistroVisitas {
public:
    int visitas() {
        return visitas_;
    }

    bool registrar() {
        if (visitas_ >= 3) {
            return false;
        }

        ++visitas_;
        return true;
    }

private:
    int visitas_ = 0;
};

int main() {
    RegistroVisitas registro;

    std::cout << "Inicio:" << registro.visitas() << "\n";

